--
-- Name: bank_transaction; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_transaction (
    txn_id bigint NOT NULL,
    txn_ref character varying(50) NOT NULL,
    acct_id bigint NOT NULL,
    txn_typ character varying(50) NOT NULL,
    txn_amt numeric(19,2) NOT NULL,
    ccy_cd character varying(3) DEFAULT 'MYR'::character varying NOT NULL,
    txn_sts character varying(20) NOT NULL,
    idempotency_key character varying(100) NOT NULL,
    crt_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    crt_by character varying(100) NOT NULL,
    dest_acct_id bigint,
    reversal_of_txn_id bigint,
    CONSTRAINT chk_bank_txn_amount CHECK ((txn_amt > (0)::numeric)),
    CONSTRAINT chk_bank_txn_currency CHECK (((ccy_cd)::text = 'MYR'::text)),
    CONSTRAINT chk_bank_txn_status CHECK (((txn_sts)::text = ANY ((ARRAY['POSTED'::character varying, 'REVERSED'::character varying])::text[]))),
    CONSTRAINT chk_bank_txn_transfer_destination CHECK (((((txn_typ)::text = 'TRANSFER'::text) AND (dest_acct_id IS NOT NULL) AND (dest_acct_id <> acct_id) AND (reversal_of_txn_id IS NULL)) OR (((txn_typ)::text = 'REVERSAL'::text) AND (reversal_of_txn_id IS NOT NULL) AND ((dest_acct_id IS NULL) OR (dest_acct_id <> acct_id))) OR (((txn_typ)::text = ANY (ARRAY[('DEPOSIT'::character varying)::text, ('WITHDRAWAL'::character varying)::text, ('FD_PLACEMENT'::character varying)::text, ('FD_INTEREST_ACCRUAL'::character varying)::text, ('FD_INTEREST_PAYOUT'::character varying)::text, ('FD_RENEWAL'::character varying)::text, ('FD_PREMATURE_WITHDRAWAL'::character varying)::text])) AND (dest_acct_id IS NULL) AND (reversal_of_txn_id IS NULL)))),
    CONSTRAINT chk_bank_txn_type CHECK (((txn_typ)::text = ANY (ARRAY[('DEPOSIT'::character varying)::text, ('WITHDRAWAL'::character varying)::text, ('TRANSFER'::character varying)::text, ('REVERSAL'::character varying)::text, ('FD_PLACEMENT'::character varying)::text, ('FD_INTEREST_ACCRUAL'::character varying)::text, ('FD_INTEREST_PAYOUT'::character varying)::text, ('FD_RENEWAL'::character varying)::text, ('FD_PREMATURE_WITHDRAWAL'::character varying)::text])))
);


