    CONSTRAINT chk_cf10aut_typ CHECK (((auth_typ)::text = ANY ((ARRAY['SIGNATORY'::character varying, 'DIRECTOR'::character varying, 'REPRESENTATIVE'::character varying, 'ACCOUNT_OPERATOR'::character varying, 'OTHER'::character varying])::text[])))
);


