    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: customer_master; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_master (
    cust_id bigint NOT NULL,
    cust_nm character varying(200) NOT NULL,
    cust_typ character varying(15) NOT NULL,
    sts character varying(15) DEFAULT 'PENDING'::character varying NOT NULL,
    crt_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    crt_by character varying(100) NOT NULL,
    upd_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    upd_by character varying(100),
    cif_no character varying(20) NOT NULL,
    CONSTRAINT chk_cf01cif_by CHECK ((length(TRIM(BOTH FROM crt_by)) > 0)),
    CONSTRAINT chk_cf01cif_nm CHECK ((length(TRIM(BOTH FROM cust_nm)) > 0)),
    CONSTRAINT chk_cf01cif_sts CHECK (((sts)::text = ANY ((ARRAY['PENDING'::character varying, 'ACTIVE'::character varying, 'INACTIVE'::character varying, 'BLOCKED'::character varying])::text[]))),
    CONSTRAINT chk_cf01cif_typ CHECK (((cust_typ)::text = ANY ((ARRAY['INDIVIDUAL'::character varying, 'CORPORATE'::character varying])::text[])))
);


--
-- Name: customer_cif_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.customer_cif_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: customer_cif_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.customer_cif_seq OWNED BY public.customer_master.cif_no;


--
-- Name: customer_corporate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_corporate (
    cust_id bigint NOT NULL,
    reg_no character varying(50) NOT NULL,
    reg_cty character varying(2) NOT NULL,
    inc_dt date,
    biz_typ character varying(50),
    crt_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    crt_by character varying(100) NOT NULL,
    upd_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    upd_by character varying(100),
    CONSTRAINT chk_cf03cor_inc CHECK (((inc_dt IS NULL) OR (inc_dt <= CURRENT_DATE))),
    CONSTRAINT chk_cf03cor_reg CHECK (((length(TRIM(BOTH FROM reg_no)) > 0) AND (length(TRIM(BOTH FROM reg_cty)) > 0)))
);


--
-- Name: customer_document; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_document (
    doc_id bigint NOT NULL,
    cust_id bigint NOT NULL,
    file_nm character varying(255) NOT NULL,
    file_typ character varying(100) NOT NULL,
    file_size bigint NOT NULL,
    storage_key character varying(500) NOT NULL,
    uploaded_by character varying(100) NOT NULL,
    uploaded_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_customer_document_size CHECK ((file_size > 0))
);


--
-- Name: customer_document_doc_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.customer_document ALTER COLUMN doc_id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.customer_document_doc_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: customer_individual; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_individual (
    cust_id bigint NOT NULL,
    dob date,
    gndr character varying(20),
    nat_cd character varying(2),
    mrtl_sts character varying(20),
    crt_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    crt_by character varying(100) NOT NULL,
    upd_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    upd_by character varying(100),
    CONSTRAINT chk_cf02ind_dob CHECK (((dob IS NULL) OR (dob <= CURRENT_DATE))),
    CONSTRAINT chk_cf02ind_gndr CHECK (((gndr IS NULL) OR ((gndr)::text = ANY ((ARRAY['MALE'::character varying, 'FEMALE'::character varying, 'OTHER'::character varying, 'NOT_SPECIFIED'::character varying])::text[])))),
    CONSTRAINT chk_cf02ind_mrtl CHECK (((mrtl_sts IS NULL) OR ((mrtl_sts)::text = ANY ((ARRAY['SINGLE'::character varying, 'MARRIED'::character varying, 'DIVORCED'::character varying, 'WIDOWED'::character varying, 'OTHER'::character varying])::text[]))))
);


