    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: customer_status_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_status_request (
